#Requires -Version 5.1
<#
.SYNOPSIS
    Installs the ExcelPatchGuard service (exe embedded below as base64) on machines with MSI-based Office 2016.
    The service does the real work in the background and writes its own log:
      C:\Windows\System32\Acceleron\ExcelPatchGuard\ExcelPatchGuard.log
    - removes Excel 2016 patch KB5002934 and newer if installed
    - searches Microsoft Update and hides Excel 2016 updates (every Wednesday more often)
    Designed for SYSTEM context (ManageEngine Endpoint Central), no user interaction.
#>

$ServiceName = 'ExcelPatchGuard'
# 32-bit PowerShell on 64-bit Windows would be redirected to SysWOW64; Sysnative avoids that
$SysDir      = if ([Environment]::Is64BitOperatingSystem -and -not [Environment]::Is64BitProcess) { Join-Path $env:SystemRoot 'Sysnative' } else { Join-Path $env:SystemRoot 'System32' }
$InstallDir  = Join-Path $SysDir 'Acceleron\ExcelPatchGuard'
$ExePath     = Join-Path $InstallDir 'ExcelPatchGuard.exe'

$KB = "KB5002934"

$Paths = @(
    "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*",
    "HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*"
)

$ExeBase64 = @'

'@

& {
    # Administrator / SYSTEM check
    $IsAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()
    ).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
    if (-not $IsAdmin) {
        Write-Host 'ERROR: Run this script as Administrator or SYSTEM.'
        return
    }

    # Is MSI-based Office 2016 installed?
    $uninstallKeys = @(
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
    )
    $officeProducts = @(Get-ItemProperty $uninstallKeys -ErrorAction SilentlyContinue |
        Where-Object {
            $_.DisplayName -like 'Microsoft Office*' -and
            $_.PSChildName -match '^\{[0-9A-F-]+0FF1CE\}$'
        })

    if (-not ($officeProducts | Where-Object { $_.DisplayVersion -like '16.*' })) {
        # Office 2016 (MSI) not found: show which Office is installed, then end
        $found = @()
        $skip  = 'Proofing|MUI|Components|Shared|OSM|Setup Metadata'
        foreach ($p in ($officeProducts | Where-Object { $_.DisplayName -notmatch $skip })) {
            $found += ('{0} ({1})' -f $p.DisplayName, $p.DisplayVersion)
        }
        $c2r = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Office\ClickToRun\Configuration' -ErrorAction SilentlyContinue
        if ($c2r) {
            $found += ('Click-to-Run {0} ({1})' -f $c2r.ProductReleaseIds, $c2r.VersionToReport)
        }
        if ($found) { Write-Host ('Office 2016 not found. Installed Office: ' + (($found | Select-Object -Unique) -join '; ')) }
        else        { Write-Host 'Office 2016 not found. No Office installation detected.' }
        return
    }

    Write-Host 'Office 2016 Found'
    Write-Host 'Installing ExcelPatchGuard service...'

    try {
        # Remove the old scheduled task from earlier versions of this script (if any)
        Unregister-ScheduledTask -TaskName 'Hide-Excel2016-Updates' -Confirm:$false -ErrorAction SilentlyContinue

        # Stop the service first so the exe can be replaced
        $svc = Get-Service -Name $ServiceName -ErrorAction SilentlyContinue
        if ($svc -and $svc.Status -ne 'Stopped') {
            Stop-Service -Name $ServiceName -Force -ErrorAction Stop
            $svc.WaitForStatus('Stopped', [TimeSpan]::FromSeconds(30))
        }

        New-Item -Path $InstallDir -ItemType Directory -Force | Out-Null
        [IO.File]::WriteAllBytes($ExePath, [Convert]::FromBase64String($ExeBase64))

        $proc = Start-Process -FilePath $ExePath -ArgumentList '--install' -Wait -PassThru -WindowStyle Hidden
        if ($proc.ExitCode -ne 0) {
            Write-Host ("ERROR: ExcelPatchGuard install failed (exit code {0})." -f $proc.ExitCode)
            return
        }
        Write-Host 'ExcelPatchGuard Installed.'

        $svc = Get-Service -Name $ServiceName -ErrorAction SilentlyContinue
        if ($svc) { try { $svc.WaitForStatus('Running', [TimeSpan]::FromSeconds(15)) } catch { } }
        $svc = Get-Service -Name $ServiceName -ErrorAction SilentlyContinue
        if ($svc -and $svc.Status -eq 'Running') { Write-Host "Service '$ServiceName' is running." }
        else { Write-Host "WARNING: Service '$ServiceName' is not running." }
		
		# ============================================================
		# Automated Silent Uninstall - Microsoft Office KB5002914
		# ============================================================

		Write-Host "`n=== $KB Silent Uninstall ===" -ForegroundColor Cyan

		# ------------------------------------------------------------
		# Function: Find KB
		# ------------------------------------------------------------

		function Get-KBEntries {

			Get-ItemProperty $Paths -ErrorAction SilentlyContinue |
				Where-Object {
					$_.DisplayName -like "*$KB*" -and
					$_.UninstallString -match "Oarpmany\.exe"
				}
		}

		# ------------------------------------------------------------
		# Main Loop
		# ------------------------------------------------------------

		while ($true) {

			$Updates = @(Get-KBEntries)

			# Nothing left -> DONE
			if ($Updates.Count -eq 0) {

				Write-Host "`n$KB is no longer installed." -ForegroundColor Green
				# Write-Host "Uninstall completed successfully." -ForegroundColor Green

				return
			}

			Write-Host "`nFound $($Updates.Count) remaining entry(s)." `
				-ForegroundColor Yellow

			# --------------------------------------------------------
			# Take ONLY ONE entry
			# --------------------------------------------------------

			$Update = $Updates[0]

			Write-Host "`nUninstalling:" -ForegroundColor Yellow
			Write-Host $Update.DisplayName

			$Command = $Update.UninstallString

			# --------------------------------------------------------
			# Parse Oarpmany command
			# --------------------------------------------------------

			if ($Command -match `
				'Oarpmany\.exe"\s+/removereleaseinpatch\s+"([^"]+)"\s+"([^"]+)"\s+"([^"]+)"\s+"([^"]+)"') {

				$ProductGUID = $Matches[1]
				$PatchGUID   = $Matches[2]

				Write-Host "Product GUID : $ProductGUID"
				Write-Host "Patch GUID   : $PatchGUID"

				# ----------------------------------------------------
				# Silent uninstall
				# ----------------------------------------------------

				$Arguments = @(
					"/package"
					$ProductGUID
					"/uninstall"
					$PatchGUID
					"/qn"
					"REBOOT=REALLYSUPPRESS"
				)

				try {

					$Process = Start-Process `
						-FilePath "$env:SystemRoot\System32\msiexec.exe" `
						-ArgumentList $Arguments `
						-Wait `
						-PassThru `
						-WindowStyle Hidden

					$ExitCode = $Process.ExitCode

					Write-Host "Exit Code: $ExitCode"

					if ($ExitCode -eq 0) {

						Write-Host "Uninstall command completed." `
							-ForegroundColor Green
					}
					elseif ($ExitCode -eq 3010) {

						Write-Host "Uninstall completed. Reboot required." `
							-ForegroundColor Yellow
					}
					else {

						Write-Host "Uninstall returned exit code $ExitCode." `
							-ForegroundColor Red

						return
					}

				}
				catch {

					Write-Host "Uninstall failed: $($_.Exception.Message)" `
						-ForegroundColor Red

					return
				}

				# ----------------------------------------------------
				# IMPORTANT:
				# Re-check KB after ONE uninstall
				# ----------------------------------------------------

				Start-Sleep -Seconds 2

				$Remaining = @(Get-KBEntries)

				if ($Remaining.Count -eq 0) {

					Write-Host "`n$KB successfully removed." `
						-ForegroundColor Green

					return
				}

				# Still present -> loop and process next entry
				Write-Host "`n$KB still detected." -ForegroundColor Yellow
				Write-Host "Moving to next entry..."

			}
			else {

				Write-Host "`nUnable to parse uninstall command:" `
					-ForegroundColor Red

				Write-Host $Command

				return
			}
		}
    } catch {
        Write-Host "ERROR: $($_.Exception.Message)"
    }
}

